                     std::cerr << "[INVOKE-TRACE] " << class_name << "."
                               << method_name << " args=" << args.size()
-                              << " regs=" << registers_size
-                              << std::endl;
+                              << " regs=" << registers_size;
+                    // S188 diag: bounded argument VALUES (ints/chars, short
+                    // strings, object ids) — the glyph-loop needs the exact
+                    // char codes reaching loadChar/getCharIndex.
+                    for (size_t vi = 0;
+                         vi < args.size() && vi < 4; ++vi) {
+                        const DalvikValue& va = args[vi];
+                        if (va.type == DalvikType::INT32 ||
+                            va.type == DalvikType::CHAR ||
+                            va.type == DalvikType::SHORT ||
+                            va.type == DalvikType::BYTE ||
+                            va.type == DalvikType::BOOLEAN)
+                            std::cerr << " a" << vi << "="
