+#!/usr/bin/env python3
+"""ag45_census.py — androguard static census over the canonical APK corpus.
+
+Per-APK JSON: package, versionCode, minSdk/targetSdk, dex count, class count,
+unique framework method refs (android/*/java/*/kotlin/*), root-package
+histogram, top const-strings. Summary TSV across the corpus.
+
+Recreated for S189 (Coder 3): the originals were lost with a recycled sandbox
+(see #560 honest note). Purpose: reference-surface vs engine-implementation
+diff -> generic base-layer gap list (message-45 directive: androguard-driven
+debugging).
+"""
+import os, sys, json, hashlib, glob
+from collections import Counter, defaultdict
+
+from loguru import logger
+logger.remove()
+from androguard.core.apk import APK
+
+APK_DIRS = [
+    "/home/z/my-project/upload/canonical_apks_restored",
+    "/home/z/my-project/upload/canonical_apks",
+    "/home/z/my-project/work/apks",
+]
+OUT_DIR = "/home/z/my-project/work/repo/evidence/s157_androguard/census"
+FW_PREFIXES = ("Landroid/", "Ljava/", "Lkotlin/", "Ljavax/", "Landroidx/", "Lcom/android/")
+
+def sha256(path, n=8192):
+    h = hashlib.sha256()
+    with open(path, "rb") as f:
+        while True:
+            b = f.read(n)
+            if not b:
+                break
+            h.update(b)
+    return h.hexdigest()
+
+def census(apk_path):
+    a = APK(apk_path)
+    package = a.get_package()
+    vc = a.get_androidversion_code()
+    min_sdk = a.get_min_sdk_version()
+    tgt_sdk = a.get_target_sdk_version()
+    perms = a.get_permissions()
+    activities = a.get_activities()
+    main_act = a.get_main_activity()
+
+    # lightweight DEX pass: reference census without full analysis first
+    import zipfile, io
+    from androguard.core.dex import DEX
+    dexes = []
+    with open(apk_path, "rb") as f:
+        z = zipfile.ZipFile(io.BytesIO(f.read()))
+        for name in sorted(n for n in z.namelist() if n.startswith("classes") and n.endswith(".dex")):
+            dexes.append(DEX(z.read(name)))
+        entries = z.namelist()
+        native_libs = sorted(n for n in entries if n.startswith("lib/") and n.endswith(".so"))
+        assets = sorted(n for n in entries if n.startswith("assets/"))
+        arsc = [n for n in entries if n.endswith("resources.arsc")]
+
+    fw_methods = set()
+    fw_fields = set()
+    root_pkgs = Counter()
+    classes_total = 0
+    const_strings = Counter()
+    for d in dexes:
+        for cls in d.get_classes():
+            cname = cls.get_name()
+            classes_total += 1
+            root = cname[1:].split("/")[0]
+            root_pkgs[root] += 1
+            for m in cls.get_methods():
+                try:
+                    if m.get_code() is None:
+                        continue
+                    insts = m.get_instructions()
+                except Exception:
+                    continue
+                for inst in insts:
+                    op = inst.get_name()
+                    if op.startswith("invoke") and op != "invoke":
+                        try:
+                            operands = inst.get_operands()
+                            if operands:
+                                ref = operands[-1][2] if len(operands[-1]) > 2 else ""
+                                # method ref string looks like: Lcls;->name(args)ret
+                                cls_ref = ref.split("->")[0]
+                                if cls_ref.startswith(FW_PREFIXES):
+                                    fw_methods.add(ref)
+                        except Exception:
+                            pass
+                    elif op.startswith("sget") or op.startswith("iget"):
+                        try:
+                            operands = inst.get_operands()
+                            if operands:
+                                ref = operands[-1][2] if len(operands[-1]) > 2 else ""
+                                cls_ref = ref.split("->")[0]
+                                if cls_ref.startswith(FW_PREFIXES):
+                                    fw_fields.add(ref)
+                        except Exception:
+                            pass
+                    elif op.startswith("const-string"):
+                        try:
+                            operands = inst.get_operands()
+                            if len(operands) > 1:
+                                s = operands[1][2]
+                                const_strings[s] += 1
+                        except Exception:
+                            pass
+
+    return {
+        "apk": os.path.basename(apk_path),
+        "sha256": sha256(apk_path),
+        "package": package,
+        "version_code": vc,
+        "min_sdk": min_sdk,
+        "target_sdk": tgt_sdk,
+        "main_activity": main_act,
+        "n_activities": len(activities),
+        "n_permissions": len(perms),
+        "permissions": sorted(perms)[:20],
+        "dex_count": len(dexes),
+        "classes_total": classes_total,
+        "fw_method_refs_unique": len(fw_methods),
+        "fw_field_refs_unique": len(fw_fields),
+        "root_packages_top": dict(root_pkgs.most_common(12)),
+        "native_libs": native_libs,
+        "n_assets": len(assets),
+        "has_resources_arsc": bool(arsc),
+        "const_strings_top": dict(const_strings.most_common(15)),
+    }
+
+def main():
+    os.makedirs(OUT_DIR, exist_ok=True)
+    seen = {}
+    for d in APK_DIRS:
+        for p in sorted(glob.glob(os.path.join(d, "*.apk"))):
+            seen[os.path.basename(p)] = p
+    rows = []
+    for name in sorted(seen):
+        p = seen[name]
+        try:
+            c = census(p)
+        except Exception as e:
+            c = {"apk": name, "error": f"{type(e).__name__}: {e}"}
+        rows.append(c)
+        with open(os.path.join(OUT_DIR, name + ".json"), "w") as f:
+            json.dump(c, f, indent=1)
+        if "error" in c:
+            print(f"ERR  {name}: {c['error'][:80]}")
+        else:
+            print(f"OK   {name}: pkg={c['package']} classes={c['classes_total']} "
+                  f"fwM={c['fw_method_refs_unique']} fwF={c['fw_field_refs_unique']} dex={c['dex_count']}")
+    tsv = os.path.join(os.path.dirname(OUT_DIR), "census_summary.tsv")
+    cols = ["apk", "package", "min_sdk", "target_sdk", "dex_count", "classes_total",
+            "fw_method_refs_unique", "fw_field_refs_unique", "n_assets", "native_libs"]
+    with open(tsv, "w") as f:
+        f.write("\t".join(cols) + "\n")
+        for c in rows:
+            if "error" in c:
+                f.write(c["apk"] + "\tERROR\n")
+                continue
+            f.write("\t".join(str(c.get(k, "")) for k in cols) + "\n")
+    print(f"summary -> {tsv}  ({len(rows)} APKs)")
+
+if __name__ == "__main__":
+    main()
