+#!/usr/bin/env python3
+"""ag45_zip_probe.py — ZIP-level APK integrity probe (pre-engine-load check).
+
+The #560 false-failure note: three tiny APKs "failed load_apk in 0 ms" —
+NOT an engine bug; the runs used a RELATIVE path that does not exist under
+work/. This probe validates, BEFORE the engine is invoked:
+  - the file exists at the ABSOLUTE path (kills the relative-path class of error)
+  - ZIP central directory parses
+  - AndroidManifest.xml + classes*.dex + resources.arsc presence
+  - native-lib ABI inventory
+  - CRC integrity of every entry (zipfile.testzip)
+
+Usage: ag45_zip_probe.py <apk> [<apk> ...]   (absolute paths REQUIRED)
+Exit 0 = all probed APKs healthy; 1 = any failure (print which).
+"""
+import sys, os, zipfile, json, hashlib
+
+def probe(path):
+    r = {"apk": path, "exists": os.path.isfile(path)}
+    if not r["exists"]:
+        r["verdict"] = "PATH_MISSING (absolute path required — see #560 relative-path law)"
+        return r
+    r["bytes"] = os.path.getsize(path)
+    h = hashlib.sha256()
+    with open(path, "rb") as f:
+        for chunk in iter(lambda: f.read(65536), b""):
+            h.update(chunk)
+    r["sha256"] = h.hexdigest()
+    try:
+        z = zipfile.ZipFile(path)
+    except Exception as e:
+        r["verdict"] = f"ZIP_OPEN_FAIL {type(e).__name__}"
+        return r
+    names = z.namelist()
+    r["entries"] = len(names)
+    r["has_manifest"] = "AndroidManifest.xml" in names
+    r["dexes"] = sorted(n for n in names if n.startswith("classes") and n.endswith(".dex"))
+    r["has_arsc"] = "resources.arsc" in names
+    r["native_libs"] = sorted(n for n in names if n.startswith("lib/") and n.endswith(".so"))
+    r["abis"] = sorted({n.split("/")[1] for n in r["native_libs"]})
+    bad = z.testzip()
+    r["crc_bad_entry"] = bad
+    ok = r["has_manifest"] and r["dexes"] and bad is None
+    r["verdict"] = "HEALTHY" if ok else "UNHEALTHY"
+    return r
+
+def main():
+    if len(sys.argv) < 2:
+        print(__doc__)
+        sys.exit(2)
+    results = [probe(p) for p in sys.argv[1:]]
+    print(json.dumps(results, indent=1))
+    sys.exit(0 if all(r["verdict"] == "HEALTHY" for r in results) else 1)
+
+if __name__ == "__main__":
+    main()
